    }

    @Test
    void jsonMalformadoRetornaPedidoInvalido() throws Exception {
        enviar("{\"itens\": 123").andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.erro").value("PEDIDO_INVALIDO"));
