                [{"nome": "Cinto", "precoUnitario": 120.00, "quantidade": 2, "pesoKg": 0.20}]
                """;
        esperarErro(PedidoJson.montar(itens, "EXPRESSA", "MENOS50", "PIX", null, "BRONZE", "SUL"), "CUPOM_NAO_APLICAVEL");
    }

