    void leve3Pague2SemTresUnidadesRetornaCupomNaoAplicavel() throws Exception {
        esperarErro(PedidoJson.montar(PedidoJson.ITENS_PADRAO, "EXPRESSA", "LEVE3PAGUE2", "PIX", null, "BRONZE", "SUL"),
